def normalize_header_name(name: str) -> str:
    parts = name.split('-')
    out = []
    for p in parts:
        if not p:
            continue
        out.append(p[0].upper() + p[1:].lower() if len(p) > 1 else p.upper())
    return '-'.join(out)

def NormalizeHeaderName(inputName):
    """Normalize an HTTP header field name to canonical Title-Case form.

    This helper converts arbitrary header names into the conventional
    hyphen-separated Title-Case representation used by many HTTP stacks.

    Args:
        inputName: Raw header name string, possibly lower-case or mixed.

    Returns:
        A Title-Case hyphenated header name string.

    Raises:
        RuntimeError: If normalization fails for any reason.

    Example:
        >>> NormalizeHeaderName('content-type')
        'Content-Type'
    """
    try:
        try:
            return '-'.join([p.capitalize() for p in inputName.split('-') if p])
        except Exception as inner:
            raise RuntimeError(f'inner normalize failed: {inner}')
    except Exception as outer:
        try:
            return str(inputName)
        except Exception:
            return ''
